#pragma once

#include <stdint.h>

/* Bitmap fonts generated by firmware/tools/gen_fonts.py (Rubik Bold). */

typedef struct {
    uint16_t cp;  /* Unicode code point (glyphs sorted ascending) */
    uint8_t adv;  /* pen advance in px */
    int8_t x0;    /* first ink column relative to the pen */
    uint8_t w;    /* ink columns */
    uint16_t off; /* index of the first column in cols */
} rg_glyph_t;

typedef struct {
    const rg_glyph_t *glyphs;
    uint16_t count;
    const uint32_t *cols; /* one per pixel column, bit n = row n of the box */
    uint8_t height;       /* box height in rows */
    uint8_t ascent;       /* rows above the baseline */
} rg_font_t;

extern const rg_font_t rg_font_count; /* 18 px '0': #-0123456789 */
extern const rg_font_t rg_font_mid;   /* 14 px '0': -0123456789: */
extern const rg_font_t rg_font_big;   /* 13 px 'H': !-.0123456789:?ABCDEFGHIJKLMNOPQRSTUVWXYZÇÖÜĞİŞ */
extern const rg_font_t rg_font_head;  /* 11 px 'H': !-.0123456789:?ABCDEFGHIJKLMNOPQRSTUVWXYZÇÖÜĞİŞ */
extern const rg_font_t rg_font_small; /* 9 px 'H': printable ASCII + Turkish letters */
